--
-- Table structure for table `episodes`
--

CREATE TABLE `episodes` (
  `id` smallint(4) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Show ID',
  `season_id` smallint(3) UNSIGNED DEFAULT NULL COMMENT 'Season ID',
  `sort_order` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Sort order',
  `competition` tinyint(1) UNSIGNED DEFAULT NULL COMMENT 'Is this a competition episode?',
  `ep_date` date DEFAULT NULL COMMENT 'Episode date',
  `title` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Episode title',
  `original_title` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Title of episode in original language.',
  `nameable` tinyint(1) UNSIGNED DEFAULT NULL COMMENT 'Binary flag for whether the episode title could have been coined by anyone.',
  `title_coined_by` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'ID of the person who coined the episode title.',
  `title_context` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Explanation of episode title, where applicable.',
  `description` varchar(2000) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'General description of the episode.',
  `notes` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Episode notes (use pipes to separate bullets).',
  `taskmaster_intro` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'How dis the Taskmaster introduce the episode?',
  `taskmaster_intro_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Any notes relating to the TM''s introduction.',
  `contestant_intro_line` varchar(512) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'The Taskmaster''s introductory line before individually intorducing the contestants.',
  `contestant_intro_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Any contextual notes about the introductory line or the introductions in general.',
  `assistant_intro` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'How was the assistant introduced?',
  `assistant_intro_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Any relevant additional contextual or translation notes.',
  `taskmaster_signoff` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'How did the TM sign off the episode?',
  `taskmaster_signoff_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Any relevant additional contextual or translation notes.',
  `winner_ids` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'ID(s) of actual episode winners',
  `winner_ids_official` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'ID(s) of officially recognised episode winner(s)',
  `winner_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Notes on the episode winner.',
  `points_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Notes about any scoring inconsistencies',
  `title_card_image_framed` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Framed title card image file.',
  `title_card_image_for_metatag` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Title card image to use for meta tags only.',
  `title_card_image_thumb` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Title card thumbnail image filename',
  `title_card_image_desc` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Title card image description',
  `secondary_image` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Filename for secondary episode image.',
  `secondary_image_desc` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Secondary image description.',
  `prize_image` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Prize image filename',
  `prize_image_desc` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Prize image description',
  `prize_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Notes on the episode proze, where a prize task is not used.'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

